import { html, nothing, type PropertyValues } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { X } from 'lucide'
import { DsElement, define } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import { SheetController } from '@/elements/controllers/sheet'
import styles from 'virtual:tw'

// Drawer.vue as <conare-drawer>: a panel that slides in from an edge over a dimmed page (the console's phone sidebar,
// console2.css .v2-side on a phone): `left` (the default) and `right` are min(300px, 84vw) and full height, `bottom` is
// the screen's width and up to 85% of its height. It slides its own size in over 240ms on the strong ease-out and out
// in 180ms; the scrim is the page at 16%. A tap on the scrim or Escape (at once) closes it, and focus returns to what
// opened it. The heading is for screen readers unless `bar` shows it in a 48px bar with a close button. Vue's
// v-model:open is the reflected `open` attribute with an `open-change` event; Vue's `title` is `heading`; the slot's
// `close` is the element's close().

/**
 * @summary A panel that slides in from an edge over a dimmed page.
 * @slot - The panel's content.
 * @fires open-change - It opened or closed (detail.value; read `open`).
 */
export class Drawer extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { heading: {}, side: { reflect: true }, bar: { type: Boolean }, open: { type: Boolean, reflect: true } }

	/** The panel's name, shown in the bar with `bar`. */
	heading = ''
	side: 'left' | 'right' | 'bottom' = 'left'
	/** The 48px bar with the heading and a close button. */
	bar = false
	/** Whether it is showing. */
	open = false

	private sheet = new SheetController(this, () => this.renderRoot.querySelector('dialog'), (open) => this.setOpen(open))

	/** Closes it, with its exit (the Vue slot's close). */
	close() {
		this.setOpen(false)
	}
	private setOpen(open: boolean) {
		if (this.open === open) return
		this.open = open
		this.emit('open-change', { value: open })
	}

	// Vue's watch(open) and onMounted: show when it opens (or starts open), hide when it closes.
	protected updated(changed: PropertyValues) {
		super.updated(changed)
		if (!changed.has('open')) return
		if (this.open) void this.sheet.show()
		else if (changed.get('open') !== undefined) void this.sheet.hide()
	}

	render() {
		return html`<dialog data-ds="drawer" class="ds-drawer" data-side=${this.side} data-shown=${ifDefined(this.sheet.shown ? 'true' : undefined)} aria-label=${this.heading} tabindex="-1" @cancel=${this.sheet.onCancel} @click=${this.sheet.onClick}>
			${this.bar
				? html`<div class="flex h-bar shrink-0 items-center gap-1 border-b border-edge pr-2 pl-4">
						<h2 class="min-w-0 flex-1 truncate type-ui-strong">${this.heading}</h2>
						<button type="button" class="inline-flex size-control-touch shrink-0 cursor-pointer items-center justify-center border border-transparent text-fg-soft transition-[color,border-color] duration-120 ease-standard hover:border-edge-strong hover:text-fg focus-visible:outline-2 focus-visible:outline-edge-focus" aria-label="close" @click=${() => this.close()}>${icon(X, 'x', { size: 14, strokeWidth: 1.5 })}</button>
					</div>`
				: nothing}
			<div class="fade-y flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain" data-sheet-body><slot></slot></div>
		</dialog>`
	}
}

define('drawer', Drawer)

/* Drawer.vue's <style>, as it is. */
.ds-drawer { position: fixed; max-width: none; max-height: none; margin: 0; padding: 0; border: 0; background: var(--ds-color-surface-subtle); color: var(--ds-color-fg); font-size: var(--ds-text-ui); line-height: var(--ds-text-ui-leading); transition: transform var(--ds-duration-slide) var(--ds-easing-out); }
.ds-drawer[open] { display: flex; flex-direction: column; }
.ds-drawer:focus { outline: none; }
.ds-drawer[data-side="left"] { inset: 0 auto 0 0; width: min(300px, 84vw); height: 100dvh; border-right: var(--ds-border-hairline) solid var(--ds-color-edge); transform: translateX(-100%); }
.ds-drawer[data-side="right"] { inset: 0 0 0 auto; width: min(300px, 84vw); height: 100dvh; border-left: var(--ds-border-hairline) solid var(--ds-color-edge); transform: translateX(100%); }
.ds-drawer[data-side="bottom"] { inset: auto 0 0; width: 100vw; max-height: 85dvh; border-top: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); transform: translateY(100%); padding-bottom: env(safe-area-inset-bottom); }
.ds-drawer[data-shown] { transform: none; transition-duration: var(--ds-duration-drawer); }
.ds-drawer::backdrop { background: var(--ds-color-scrim-light); opacity: 0; transition: opacity var(--ds-duration-slide) var(--ds-easing-out); }
.ds-drawer[data-shown]::backdrop { opacity: 1; transition-duration: var(--ds-duration-drawer); }
@media (prefers-reduced-motion: reduce) {
  .ds-drawer, .ds-drawer[data-side] { transform: none; opacity: 0; transition: opacity var(--ds-duration-slide) var(--ds-easing-out); }
  .ds-drawer[data-shown] { opacity: 1; }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit'
import { firstFocusable } from '@/elements/lib/popover'

/**
 * useSheet as a Lit controller: a native modal dialog that slides (Sheet, Drawer): showModal keeps focus inside and
 * the page inert; the panel and its scrim come in on `data-shown` and leave on its removal, closing once the exit
 * transition has run (read from CSS, so reduced motion and the tokens decide). Escape closes at once (keyboard actions
 * don't animate); the scrim closes it; focus returns to what opened it, through shadow roots. Focus starts on the first
 * control in `[data-autofocus]` (in the page's content or the panel) or the body, else the panel. The element calls
 * show() and hide() when its `open` changes and passes `setOpen` for Escape and the scrim.
 */
export class SheetController implements ReactiveController {
	shown = false
	private returnTo: HTMLElement | null = null
	private timer?: ReturnType<typeof setTimeout>

	constructor(
		private host: ReactiveControllerHost & HTMLElement,
		private dialog: () => HTMLDialogElement | null,
		private setOpen: (open: boolean) => void,
		private options: { dismissable?: () => boolean } = {},
	) {
		host.addController(this)
	}
	hostDisconnected() {
		clearTimeout(this.timer)
	}

	private exitMs(el: HTMLElement) {
		const parts = getComputedStyle(el).transitionDuration.split(',').map((s) => Number.parseFloat(s) * (s.trim().endsWith('ms') ? 1 : 1000))
		return Math.max(0, ...parts.filter((n) => !Number.isNaN(n)))
	}
	private setShown(v: boolean) {
		this.shown = v
		this.host.requestUpdate()
	}

	async show() {
		const d = this.dialog()
		if (!d || d.open) return
		clearTimeout(this.timer)
		// The focused element itself, inside shadow roots, not the host it sits in.
		let active = document.activeElement as HTMLElement | null
		while (active?.shadowRoot?.activeElement) active = active.shadowRoot.activeElement as HTMLElement
		this.returnTo = active
		d.showModal()
		const start = this.host.querySelector<HTMLElement>('[data-autofocus]') ?? d.querySelector<HTMLElement>('[data-autofocus]') ?? firstFocusable(d.querySelector<HTMLElement>('[data-sheet-body]'))
		;(start ?? d).focus({ preventScroll: true })
		// One frame at the closed state, so the transition has somewhere to start.
		await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)))
		this.setShown(true)
	}
	private finish() {
		this.dialog()?.close()
		this.returnTo?.focus({ preventScroll: true })
		this.returnTo = null
	}
	async hide(instant = false) {
		const d = this.dialog()
		if (!d?.open) return
		this.setShown(false)
		if (instant) return this.finish()
		await this.host.updateComplete
		// ds-latency: the dialog stays in the top layer until its exit has played.
		this.timer = setTimeout(() => this.finish(), this.exitMs(d))
	}

	/** Escape: at once, no exit motion. */
	onCancel = (event: Event) => {
		event.preventDefault()
		if (this.options.dismissable && !this.options.dismissable()) return
		this.setOpen(false)
		void this.hide(true)
	}
	/** A press on the scrim lands on the dialog element itself. */
	onClick = (event: MouseEvent) => {
		if (event.target === this.dialog() && (!this.options.dismissable || this.options.dismissable())) this.setOpen(false)
	}
}
